CREATE TABLE IF NOT EXISTS learning_events (id TEXT PRIMARY KEY, class_id TEXT NOT NULL, student_id TEXT, session_id TEXT, event_type TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT, payload TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL, FOREIGN KEY (class_id) REFERENCES classes(id), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (session_id) REFERENCES lesson_sessions(id));
CREATE TABLE IF NOT EXISTS student_insights (id TEXT PRIMARY KEY, class_id TEXT NOT NULL, student_id TEXT NOT NULL, completion_rate REAL NOT NULL DEFAULT 0, assignment_rate REAL NOT NULL DEFAULT 0, activity_rate REAL NOT NULL DEFAULT 0, average_score REAL, attention_reason TEXT NOT NULL DEFAULT '', calculated_at TEXT NOT NULL, UNIQUE (class_id, student_id), FOREIGN KEY (class_id) REFERENCES classes(id), FOREIGN KEY (student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS class_insights (id TEXT PRIMARY KEY, class_id TEXT NOT NULL UNIQUE, preview_completion_rate REAL NOT NULL DEFAULT 0, assignment_completion_rate REAL NOT NULL DEFAULT 0, activity_participation_rate REAL NOT NULL DEFAULT 0, average_score REAL, score_distribution TEXT NOT NULL DEFAULT '{}', calculated_at TEXT NOT NULL, FOREIGN KEY (class_id) REFERENCES classes(id));
CREATE INDEX IF NOT EXISTS idx_learning_events_class_time ON learning_events(class_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_learning_events_student ON learning_events(student_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_student_insights_class ON student_insights(class_id);
